    JavaScriptConfig config = mapper.readValue(
        mapper.writeValueAsString(
            mapper.readValue(
                json,
                JavaScriptConfig.class
            )
        ), JavaScriptConfig.class
    );

    Assert.assertTrue(config.isEnabled());
  }

